import{_ as t,c as i,o as a,al as o}from"./chunks/framework.CT7RwC5a.js";const p=JSON.parse('{"title":"Test MC_07 - VIO (Visual-Inertial Odometry)","description":"","frontmatter":{},"headers":[],"relativePath":"ko/test_cards/mc_07_vio.md","filePath":"ko/test_cards/mc_07_vio.md"}'),r={name:"ko/test_cards/mc_07_vio.md"};function l(n,e,s,d,c,h){return a(),i("div",null,e[0]||(e[0]=[o('<h1 id="test-mc-07-vio-visual-inertial-odometry" tabindex="-1">Test MC_07 - VIO (Visual-Inertial Odometry) <a class="header-anchor" href="#test-mc-07-vio-visual-inertial-odometry" aria-label="Permalink to &quot;Test MC_07 - VIO (Visual-Inertial Odometry)&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>To test that external vision (VIO) works as expected</p><h2 id="preflight" tabindex="-1">Preflight <a class="header-anchor" href="#preflight" aria-label="Permalink to &quot;Preflight&quot;">​</a></h2><p>Disconnect all GPS / compasses and ensure vehicle is using VIO for navigation</p><p>Ensure that the drone can go into Altitude / Position flight mode while still on the ground</p><p>Ensure there are no other sources of positioning besides VIO:</p><ul><li><a href="./../advanced_config/parameter_reference.html#EKF2_OF_CTRL">EKF2_OF_CTRL</a>: <code>0</code></li><li><a href="./../advanced_config/parameter_reference.html#EKF2_GPS_CTRL">EKF2_GPS_CTRL</a>: <code>0</code></li><li><a href="./../advanced_config/parameter_reference.html#EKF2_EV_CTRL">EKF2_EV_CTRL</a>: <code>15</code></li><li><a href="./../advanced_config/parameter_reference.html#SYS_HAS_MAG">SYS_HAS_MAG</a>: <code>0</code></li></ul><h2 id="flight-tests" tabindex="-1">Flight Tests <a class="header-anchor" href="#flight-tests" aria-label="Permalink to &quot;Flight Tests&quot;">​</a></h2><p>❏ Altitude flight mode</p><p>    ❏ Vertical position should hold current value with stick centered</p><p>    ❏ Pitch/Roll/Yaw response 1:1</p><p>    ❏ Throttle response set to climb/descent rate</p><p>❏ Position flight mode</p><p>    ❏ Horizontal position should hold current value with stick centered</p><p>    ❏ Vertical position should hold current value with stick centered</p><p>    ❏ Throttle response set to climb/descent rate</p><p>    ❏ Pitch/Roll/Yaw response set to pitch/roll/yaw rates</p><h2 id="착륙" tabindex="-1">착륙 <a class="header-anchor" href="#착륙" aria-label="Permalink to &quot;착륙&quot;">​</a></h2><p>❏ Land in either Position or Altitude mode with the throttle below 40%</p><p>❏ Upon touching ground, copter should disarm automatically within 2 seconds (default: see <a href="./../advanced_config/parameter_reference.html#COM_DISARM_LAND">COM_DISARM_LAND</a>)</p><h2 id="예상-결과" tabindex="-1">예상 결과 <a class="header-anchor" href="#예상-결과" aria-label="Permalink to &quot;예상 결과&quot;">​</a></h2><ul><li>추력을 올릴 때 서서히 이륙한다</li><li>Drone should hold altitude in Altitude Flight mode without wandering</li><li>Drone should hold position within 1 meter in Position Flight mode without pilot moving sticks</li><li>위에 언급한 어떤 비행 모드에서도 떨림이 나타나서는 안됨</li><li>지면에 착륙시, 콥터가 지면에서 튀면 안됨</li></ul>',23)]))}const u=t(r,[["render",l]]);export{p as __pageData,u as default};
